INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_560001', 'MCQ',
 'A client scheduled for a lumbar laminectomy asks the nurse what the operation will actually do. Which explanation is correct?',
 'A laminectomy removes the lamina, the bony arch at the back of a vertebra, so that a nerve root compressed by a herniated disc or by bony overgrowth is decompressed. The aim is to relieve the radiating pain, numbness and weakness caused by that pressure. It does not repair the spinal cord, and fusing the vertebrae is a separate procedure that may or may not be added.',
 '{"options":[{"id":"A","text":"A portion of the bony arch at the back of the vertebra is removed so that pressure on the trapped nerve root is relieved."},{"id":"B","text":"The damaged spinal cord is repaired with a nerve graft so that normal sensation returns."},{"id":"C","text":"The vertebrae are permanently locked together so that the lower back can no longer bend."},{"id":"D","text":"A metal rod is inserted along the spine to correct a sideways curvature."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Removing the lamina decompresses the nerve root, which is the whole purpose of the operation.","B":"Incorrect. A laminectomy does not repair the spinal cord; damaged cord tissue cannot be grafted back.","C":"Incorrect. That describes a spinal fusion, which is an additional procedure sometimes performed with a laminectomy.","D":"Incorrect. Rod insertion is used for scoliosis correction, not for nerve root decompression."}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Musculoskeletal',
 'Laminectomy', 'Purpose of surgery',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_560002', 'SELECT_N',
 'A client attends the outpatient clinic with a suspected herniated lumbar disc. Which 3 findings would the nurse expect if a nerve root is being compressed?',
 'Nerve root compression produces a triad along the distribution of that root: radiating pain, altered sensation and motor weakness. The findings follow the path of the nerve rather than spreading over the whole back. Warm reddened skin and bounding pulses point to inflammation or vascular change, not to a compressed root.',
 '{"options":[{"id":"A","text":"Pain radiating down the back of one leg to below the knee"},{"id":"B","text":"Numbness and tingling along the outer border of the same foot"},{"id":"C","text":"Weakness of that leg when asked to pull the foot upwards"},{"id":"D","text":"A bounding pedal pulse in the affected leg"},{"id":"E","text":"Warm, reddened skin spread across the whole lower back"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Radiating pain along the nerve pathway is the classic first sign of root compression.","B":"Correct. Paraesthesia in the dermatome supplied by the compressed root is expected.","C":"Correct. Motor weakness in the muscles supplied by that root confirms the compression.","D":"Incorrect. Pulses are unaffected by nerve root compression; a bounding pulse is a vascular finding.","E":"Incorrect. Widespread warmth and redness suggest infection or inflammation, not root compression."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological',
 'Lumbar disc herniation', 'Nerve root compression',
 'Easy', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560003', 'MCQ',
 'A client returns to the ward after a cervical laminectomy. Which assessment is the PRIORITY during the first hours after surgery?',
 'The complication to watch for after spinal surgery is set by the level operated on. At the cervical level, oedema or a haematoma close to the surgical site can compromise the airway and the nerve supply to the diaphragm, so breathing is the priority. Bladder emptying is the lumbar concern and a paralytic ileus is the thoracic concern.',
 '{"options":[{"id":"A","text":"Respiratory rate, depth and the ability to take a deep breath"},{"id":"B","text":"Bladder distension and the time of the first void"},{"id":"C","text":"Bowel sounds in all four quadrants"},{"id":"D","text":"Presence of a wound drain at the operative site"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Swelling at the cervical level threatens the airway and diaphragmatic function, which makes breathing the priority.","B":"Incorrect. Urinary retention is the concern after lumbar surgery, not after cervical surgery.","C":"Incorrect. A paralytic ileus is more likely after thoracic surgery and is not the first-hour priority here.","D":"Incorrect. Checking the drain is part of routine care but does not outrank airway and breathing."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Medical-Surgical', 'Musculoskeletal',
 'Cervical laminectomy', 'Post-operative priority',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560004', 'MCQ',
 'Eight hours after a lumbar laminectomy a client has not passed urine and reports lower abdominal fullness. Which action should the nurse take FIRST?',
 'Lumbar surgery, anaesthesia and opioid analgesia all depress bladder emptying, so urinary retention is the expected post-operative problem at this level. Assessment comes before intervention: palpating and percussing the suprapubic area, or scanning the bladder, confirms whether the bladder is actually distended before a catheter is considered. Catheterising without that check exposes the client to infection risk for nothing.',
 '{"options":[{"id":"A","text":"Palpate and percuss the suprapubic area to confirm bladder distension"},{"id":"B","text":"Insert an indwelling urinary catheter"},{"id":"C","text":"Increase the rate of the intravenous infusion"},{"id":"D","text":"Ask the client to walk unaided to the toilet"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Confirming that the bladder is distended is the assessment step that must come before any intervention.","B":"Incorrect. Catheterisation may follow, but it is invasive and should not precede assessment.","C":"Incorrect. Adding fluid to an already distended bladder worsens the problem.","D":"Incorrect. Walking unaided so soon after lumbar surgery is unsafe, and it does not address the retention."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Genitourinary',
 'Lumbar laminectomy', 'Urinary retention',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560005', 'SATA',
 'A nurse and a healthcare assistant are turning a client on the first day after a laminectomy. Which actions show correct log-rolling technique? Select all that apply.',
 'Log rolling keeps the spine in one straight line so that no twisting or bending force reaches the operative site. The head, shoulders, hips and legs must move together as a single unit, with the bed flat and a pillow supporting the knees and back. Anything that asks the client to pull, twist or lead with one body part defeats the purpose.',
 '{"options":[{"id":"A","text":"Lower the bed to a flat position before turning"},{"id":"B","text":"Turn the head, shoulders, hips and legs together as one unit"},{"id":"C","text":"Place a pillow between the knees before the turn"},{"id":"D","text":"Use a draw sheet and two staff members to make the turn"},{"id":"E","text":"Ask the client to grasp the side rail and pull over to the side"},{"id":"F","text":"Turn the shoulders first and let the hips follow a moment later"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. A flat bed keeps the spine neutral during the turn.","B":"Correct. Moving the body as one unit is the defining feature of log rolling.","C":"Correct. A pillow between the knees keeps the hips aligned and prevents the spine twisting.","D":"Correct. A draw sheet and two staff members allow the whole body to move together.","E":"Incorrect. Pulling on a side rail twists the spine and must be avoided.","F":"Incorrect. Turning the shoulders ahead of the hips is exactly the twisting movement log rolling prevents."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal',
 'Laminectomy', 'Log rolling',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560006', 'MCQ',
 'A newly qualified nurse reads the post-operative instructions written for a client who had a lumbar laminectomy this morning. Which instruction should the nurse QUESTION?',
 'Sitting loads the lumbar discs more heavily than either standing or lying flat, because the weight of the upper body is transmitted through a flexed lumbar spine. Prolonged sitting is therefore restricted in the early weeks, while walking and lying flat are actively encouraged. An instruction to sit for long stretches contradicts the whole activity plan and must be checked with the surgeon.',
 '{"options":[{"id":"A","text":"Sit out in an upright chair for two hours after each meal"},{"id":"B","text":"Walk in the corridor several times a day as tolerated"},{"id":"C","text":"Lie flat on the bed between walks rather than propped up"},{"id":"D","text":"Log roll onto the side before getting out of bed"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Prolonged sitting places the greatest load on the lumbar spine and is restricted after this surgery.","B":"Incorrect. Walking is encouraged and does not need to be questioned.","C":"Incorrect. Lying flat keeps the spine neutral and is appropriate.","D":"Incorrect. Log rolling is the correct way to get out of bed after spinal surgery."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Medical-Surgical', 'Musculoskeletal',
 'Laminectomy', 'Post-operative activity',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_560007', 'MATRIX',
 'A nurse is preparing discharge teaching for a client who had a laminectomy. For each instruction, indicate whether it is a restriction that lifts once healing is complete or a habit the client should keep for life.',
 'Some post-laminectomy restrictions exist only while the surgical site heals and are reviewed at the follow-up appointment, such as not driving and limiting how long the client sits at one time. Others are lifelong protective habits, because the spine remains vulnerable to the same forces that produced the original problem. Separating the two prevents both premature return to risky activity and unnecessary lifelong restriction.',
 '{"rows":[{"id":"r1","text":"Do not drive until the surgeon gives permission at the follow-up review"},{"id":"r2","text":"Bend at the knees and keep a load close to the body when lifting"},{"id":"r3","text":"Limit sitting to about 30 minutes at a time for the first few weeks"},{"id":"r4","text":"Keep body weight within the recommended range"},{"id":"r5","text":"Avoid twisting the trunk when reaching for an object"}],"columns":[{"id":"c1","text":"Temporary restriction"},{"id":"c2","text":"Lifelong habit"}],"row_label":"Discharge instruction"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c2"},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Musculoskeletal',
 'Laminectomy', 'Discharge restrictions',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select one column for each row.', 5, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560008', 'SATA',
 'A client has had a spinal fusion using a bone graft taken from the iliac crest. Which statements about the donor site are accurate? Select all that apply.',
 'When bone is taken from the client own iliac crest the donor site is a second surgical wound, and it is frequently the more painful of the two and the one that drains more. It needs its own dressing, inspection and analgesia. Because the bone belongs to the client, there is no rejection risk at this site.',
 '{"options":[{"id":"A","text":"The donor site is often more painful than the spinal incision"},{"id":"B","text":"The donor site usually drains more than the spinal incision"},{"id":"C","text":"The donor site needs its own dressing and regular inspection"},{"id":"D","text":"The donor site is the site at which graft rejection would occur"},{"id":"E","text":"Pain at the donor site indicates that the fusion has failed"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Harvesting bone from the iliac crest commonly produces more pain than the spinal wound itself.","B":"Correct. The cancellous bone surface at the donor site oozes, so more drainage is expected there.","C":"Correct. It is a separate surgical wound and is assessed and dressed in its own right.","D":"Incorrect. Bone taken from the same client cannot be rejected; rejection is a risk only with donated bone.","E":"Incorrect. Donor site pain is expected and says nothing about whether the fusion has taken."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal',
 'Spinal fusion', 'Bone graft donor site',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_TF_560009', 'TF',
 'When a spinal fusion is performed using bone harvested from the iliac crest of the client being operated on, the body may reject the graft.',
 'Bone taken from the same person is an autograft, so the immune system recognises it as self and rejection cannot occur. Rejection is a consideration only when donated bone from a bone bank, an allograft, is used. The trade-off is that the autograft creates a second painful wound while the allograft avoids that but carries rejection and disease-transmission risk.',
 '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Bone from the same client is recognised as self and cannot be rejected.","B":"Correct. Rejection is a risk only with donated bone from a bone bank, not with the client own bone."}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Musculoskeletal',
 'Spinal fusion', 'Bone graft rejection',
 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_CLZ_560010', 'CLOZE',
 'Three clients return to the ward after a laminectomy performed at different levels of the spine. For the client operated on at the cervical level the nurse watches most closely for {1}. For the client operated on at the thoracic level the nurse watches most closely for {2}. For the client operated on at the lumbar level the nurse watches most closely for {3}.',
 'The post-operative complication that dominates after spinal surgery is decided by the level of the operation, because that level determines which nerves and muscles are affected by the surgical oedema. Cervical surgery threatens breathing and the arms, thoracic surgery weakens the abdominal muscles used for coughing and slows the gut, and lumbar surgery affects the bladder and the legs. Naming the level therefore names the complication to watch for.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"laboured breathing and a weakening hand grip"},{"id":"c2","text":"a distended abdomen with absent bowel sounds"},{"id":"c3","text":"a bladder that fills without being emptied"}]},{"id":"b2","choices":[{"id":"c1","text":"a weakening hand grip"},{"id":"c2","text":"a distended abdomen with absent bowel sounds and an ineffective cough"},{"id":"c3","text":"loss of sensation over the face"}]},{"id":"b3","choices":[{"id":"c1","text":"laboured breathing"},{"id":"c2","text":"an ineffective cough"},{"id":"c3","text":"urinary retention with weakness in the legs"}]}]}'::jsonb,
 '{"answers":{"b1":"c1","b2":"c2","b3":"c3"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological',
 'Laminectomy', 'Level-specific complications',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Complete the sentence by choosing from each drop-down.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_560011', 'MCQ',
 'A 54-year-old client tells the practice nurse that a burning pain rises behind the breastbone within an hour of the evening meal, and that it is worst after going to bed. Which condition do these findings suggest?',
 'A hiatal hernia allows part of the stomach to slide upward through the diaphragm, so gastric contents reflux into the oesophagus. Gravity is the key to the pattern: symptoms appear after eating and worsen when the client lies down, which is why they are typically worst at night. Pain that is relieved rather than provoked by lying flat points elsewhere.',
 '{"options":[{"id":"A","text":"Hiatal hernia with reflux of gastric contents"},{"id":"B","text":"Dumping syndrome"},{"id":"C","text":"Perforated peptic ulcer"},{"id":"D","text":"Acute cholecystitis"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Burning retrosternal pain after meals that is worse lying down is the classic reflux pattern of a hiatal hernia.","B":"Incorrect. Dumping syndrome follows gastric surgery and produces sweating, palpitations and cramping, not retrosternal burning.","C":"Incorrect. A perforated ulcer causes sudden severe pain with a rigid abdomen, not a nightly burning sensation.","D":"Incorrect. Cholecystitis causes right upper quadrant pain radiating to the shoulder, typically after fatty food."}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Gastrointestinal',
 'Hiatal hernia', 'Recognising the pattern',
 'Very easy', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560012', 'SATA',
 'A client who had a partial gastrectomy three weeks ago reports feeling unwell about 20 minutes after eating. Which findings would support a diagnosis of dumping syndrome? Select all that apply.',
 'After gastric surgery the pylorus no longer controls emptying, so a concentrated meal is dumped into the small bowel. Fluid is drawn from the circulation into the bowel lumen, producing vasomotor symptoms such as dizziness, palpitations, sweating and pallor, alongside abdominal cramping and an urgent loose stool. The timing is the giveaway: this early cluster appears within about 30 minutes of eating.',
 '{"options":[{"id":"A","text":"Dizziness and a feeling of faintness"},{"id":"B","text":"Palpitations with a pulse of 108 beats per minute"},{"id":"C","text":"Sweating with pallor"},{"id":"D","text":"Abdominal cramping followed by an urgent loose stool"},{"id":"E","text":"Burning retrosternal pain relieved by sitting upright"},{"id":"F","text":"A dry mouth with reduced urine output over several days"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Fluid shifting into the bowel reduces circulating volume and causes dizziness.","B":"Correct. Tachycardia is part of the vasomotor response to the sudden fluid shift.","C":"Correct. Sweating and pallor are classic vasomotor features of early dumping.","D":"Correct. The rapid osmotic load into the jejunum produces cramping and urgent diarrhoea.","E":"Incorrect. Retrosternal burning relieved by sitting upright describes reflux from a hiatal hernia.","F":"Incorrect. Dumping symptoms are episodic and meal-related, not a gradual dehydration picture over days."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Gastrointestinal',
 'Dumping syndrome', 'Recognising the pattern',
 'Easy', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MMR_560013', 'MATRIX_MR',
 'A nurse teaches two clients on the same ward: one has a hiatal hernia and one has dumping syndrome after gastric surgery. For each instruction, indicate which client it applies to. An instruction may apply to both.',
 'The two conditions are close to mirror images. A hiatal hernia is a problem of contents travelling upward, so the client stays upright and does everything possible to help the stomach empty and stay empty. Dumping syndrome is a problem of contents leaving the stomach too fast, so the client lies down, keeps fluid away from food and slows the meal down. Small frequent meals are the one instruction both share.',
 '{"rows":[{"id":"r1","text":"Lie down for about 30 minutes after eating"},{"id":"r2","text":"Stay sitting upright for at least an hour after eating"},{"id":"r3","text":"Eat small, frequent meals rather than three large ones"},{"id":"r4","text":"Take fluids between meals rather than with them"},{"id":"r5","text":"Avoid eating in the three hours before going to bed"},{"id":"r6","text":"Reduce sugary foods and increase protein at every meal"}],"columns":[{"id":"c1","text":"Hiatal hernia"},{"id":"c2","text":"Dumping syndrome"}],"row_label":"Instruction"}'::jsonb,
 '{"cells":{"r1":["c2"],"r2":["c1"],"r3":["c1","c2"],"r4":["c2"],"r5":["c1"],"r6":["c2"]},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Gastrointestinal',
 'Hiatal hernia and dumping syndrome', 'Distinguishing the management',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 7, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560014', 'SATA',
 'A nurse is teaching a client who has developed dumping syndrome after gastric surgery. Which dietary instructions should be included? Select all that apply.',
 'Dietary management aims to slow the delivery of food into the small bowel and to reduce its osmotic pull. Protein and fat empty more slowly than simple sugars, so meals are built around them while sugary foods and drinks are limited. Keeping fluids away from the meal and lying down afterwards both reduce the speed at which the stomach empties.',
 '{"options":[{"id":"A","text":"Eat six small meals through the day instead of three large ones"},{"id":"B","text":"Take fluids at least 30 minutes before or after a meal, not with it"},{"id":"C","text":"Increase the protein and fat content of meals"},{"id":"D","text":"Lie down on the left side for about 30 minutes after eating"},{"id":"E","text":"Take a sweet drink with each meal to keep the energy level up"},{"id":"F","text":"Remain sitting upright for two hours after every meal"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Smaller volumes reduce the osmotic load delivered to the jejunum at any one time.","B":"Correct. Separating fluids from food slows gastric emptying.","C":"Correct. Protein and fat leave the stomach more slowly than simple carbohydrate.","D":"Correct. Lying down after eating uses gravity to delay emptying and reduces the vasomotor response.","E":"Incorrect. Simple sugars draw fluid into the bowel and are the main trigger of an attack.","F":"Incorrect. Sitting upright is the advice for reflux from a hiatal hernia; it worsens dumping."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Gastrointestinal',
 'Dumping syndrome', 'Dietary management',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560015', 'SATA',
 'A client with a hiatal hernia asks the community nurse what can be done at home to reduce the symptoms. Which measures should the nurse suggest? Select all that apply.',
 'Every effective measure for a hiatal hernia either uses gravity to keep gastric contents down or reduces the pressure pushing them up. Raising the head of the bed, avoiding late meals and loosening tight clothing all work in this way. Smoking lowers the tone of the lower oesophageal sphincter, so stopping directly reduces reflux.',
 '{"options":[{"id":"A","text":"Raise the head of the bed on blocks about 15 to 20 centimetres"},{"id":"B","text":"Avoid eating in the three hours before bedtime"},{"id":"C","text":"Avoid tight belts and waistbands"},{"id":"D","text":"Stop smoking"},{"id":"E","text":"Lie down for half an hour after each meal"},{"id":"F","text":"Take a large drink of water at bedtime"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Raising the head of the bed keeps gastric contents below the diaphragm overnight.","B":"Correct. An empty stomach at bedtime removes the material that would otherwise reflux.","C":"Correct. Tight clothing raises intra-abdominal pressure and pushes contents upward.","D":"Correct. Smoking reduces lower oesophageal sphincter tone and worsens reflux.","E":"Incorrect. Lying down after eating is the advice for dumping syndrome and makes reflux worse.","F":"Incorrect. A large volume at bedtime distends the stomach at exactly the wrong time."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Gastrointestinal',
 'Hiatal hernia', 'Lifestyle teaching',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560016', 'MCQ',
 'A client who has dumping syndrome after gastric surgery describes the new eating routine at a follow-up appointment. Which statement indicates that further teaching is needed?',
 'The single most provocative combination for dumping syndrome is a large volume of fluid taken together with a concentrated sugar load, because both accelerate emptying and increase the osmotic pull into the bowel. Fruit juice with a meal delivers exactly that. The other statements describe the correct routine of small frequent meals, protein-rich food and lying down afterwards.',
 '{"options":[{"id":"A","text":"I have a large glass of fruit juice with my lunch to help the food go down."},{"id":"B","text":"I lie down on my bed for half an hour after I eat."},{"id":"C","text":"I have six small meals spread through the day."},{"id":"D","text":"I have added eggs and fish to most of my meals."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Fluid with a meal, and a sugary fluid in particular, is the strongest trigger of an attack and shows the teaching has not been understood.","B":"Incorrect. Lying down after eating slows gastric emptying and is correct advice.","C":"Incorrect. Small frequent meals reduce the load delivered to the bowel and are correct.","D":"Incorrect. Increasing protein slows emptying and is exactly what is recommended."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Gastrointestinal',
 'Dumping syndrome', 'Evaluating teaching',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560017', 'MCQ',
 'Two hours after breakfast a client who had a gastrectomy six weeks ago becomes shaky, sweaty, anxious and intensely hungry. Which explanation should the nurse give?',
 'Late dumping occurs about one and a half to three hours after eating and is a reactive hypoglycaemia. The rapid delivery of carbohydrate into the jejunum causes a sharp rise in blood glucose, which triggers an exaggerated insulin release, and the glucose then falls below normal. Early dumping, within 30 minutes, is the fluid-shift picture instead. Immediate management is a small carbohydrate snack; prevention is the same low-sugar, high-protein diet.',
 '{"options":[{"id":"A","text":"A rapid rise in blood glucose after eating triggered an excess release of insulin, and the blood glucose has now fallen too low."},{"id":"B","text":"Fluid has moved rapidly into the bowel and reduced the circulating blood volume."},{"id":"C","text":"Acid has refluxed into the oesophagus because the remaining stomach is smaller."},{"id":"D","text":"The stomach is emptying too slowly because the vagus nerve was divided during surgery."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Late dumping is a reactive hypoglycaemia occurring one and a half to three hours after a meal.","B":"Incorrect. The fluid shift explains early dumping within 30 minutes of eating, not symptoms at two hours.","C":"Incorrect. Reflux produces burning pain, not shakiness, sweating and hunger.","D":"Incorrect. Delayed emptying would not produce this cluster, and the problem after gastrectomy is emptying that is too fast."}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Gastrointestinal',
 'Dumping syndrome', 'Late dumping and hypoglycaemia',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560018', 'MCQ',
 'A client with a haemopneumothorax has two chest tubes in place, one sited near the apex of the lung and one sited at the base. Which statement by the nurse correctly describes their purpose?',
 'Air is lighter than fluid and collects at the top of the pleural space, while blood and other fluid settle at the bottom. A tube placed high, at about the second intercostal space, therefore removes air, and a tube placed low, at about the eighth or ninth intercostal space, removes blood and fluid. A client with both air and blood in the pleural space needs both.',
 '{"options":[{"id":"A","text":"The apical tube removes air and the basilar tube removes blood and fluid."},{"id":"B","text":"The apical tube removes blood and the basilar tube removes air."},{"id":"C","text":"Both tubes remove air; the second is kept as a spare in case the first blocks."},{"id":"D","text":"The apical tube is used to instil medication and the basilar tube drains it away."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Air rises to the apex and fluid settles at the base, so each tube is placed where its target collects.","B":"Incorrect. This reverses the placement; blood settles at the base, not the apex.","C":"Incorrect. Chest tubes are not inserted as spares; each has a specific target.","D":"Incorrect. Chest tubes drain the pleural space; they are not a medication route in this situation."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Apical and basilar placement',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_560019', 'MATRIX',
 'A nurse checks the chest drainage unit of a client who has a pneumothorax and is receiving suction. For each finding, indicate whether it is expected or unexpected.',
 'In a wet suction unit, gentle continuous bubbling belongs in the suction-control chamber only. In the water-seal chamber, fluctuation with breathing is expected and bubbling should appear only intermittently, when the client coughs or exhales forcefully and trapped air is expelled. Continuous water-seal bubbling means air is entering the system from a leak, and a water seal that has stopped fluctuating means either the lung has re-expanded or, more urgently, the tube is obstructed.',
 '{"rows":[{"id":"r1","text":"The fluid in the water-seal chamber rises and falls as the client breathes"},{"id":"r2","text":"Bubbling appears in the water-seal chamber only when the client coughs"},{"id":"r3","text":"Continuous bubbling in the water-seal chamber throughout the respiratory cycle"},{"id":"r4","text":"Gentle continuous bubbling in the suction-control chamber"},{"id":"r5","text":"Drainage of 120 mL of bright red blood in the past hour"},{"id":"r6","text":"Fluctuation in the water-seal chamber has stopped and the client is suddenly breathless"}],"columns":[{"id":"c1","text":"Expected"},{"id":"c2","text":"Unexpected"}],"row_label":"Finding"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c1","r5":"c2","r6":"c2"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Expected and abnormal bubbling',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select one column for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560020', 'MCQ',
 'While a client with a chest tube is being repositioned, the tubing separates from the drainage unit and the water seal is broken. Which action should the nurse take FIRST?',
 'The immediate danger of a broken water seal is that atmospheric air travels back along the open tube into the pleural space. The first move is the one that closes that pathway at once, which is to occlude the tube close to the chest wall. That occlusion is a holding measure of seconds only, because a clamped tube in a client with an air leak allows pressure to build and a tension pneumothorax to develop; a water seal must be re-established without delay.',
 '{"options":[{"id":"A","text":"Clamp the chest tube close to the chest wall"},{"id":"B","text":"Telephone the surgeon to report the disconnection"},{"id":"C","text":"Send for a replacement drainage unit from the store room"},{"id":"D","text":"Sit the client upright and give oxygen by face mask"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Occluding the tube immediately stops atmospheric air travelling back into the pleural space while the system is restored.","B":"Incorrect. The surgeon must be informed, but not before the open pathway into the chest is closed.","C":"Incorrect. Fetching equipment leaves the tube open in the meantime.","D":"Incorrect. Oxygen and positioning help the client breathe but do nothing about the open system."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Broken water seal',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_560021', 'MCQ',
 'A chest tube has become disconnected from its drainage unit and a colleague has gone to fetch a replacement unit. Which action is the BEST way for the nurse to protect the client while waiting?',
 'A clamped tube stops air entering the chest but also traps any air escaping from the lung, so pressure can build and produce a tension pneumothorax. Submerging the open end of the tube about 2 cm below the surface of sterile water recreates a one-way water seal: trapped air bubbles out and no air is drawn back in. This is why clamping is a first move measured in seconds while the water seal is the sustainable answer.',
 '{"options":[{"id":"A","text":"Place the open end of the chest tube about 2 cm below the surface of a container of sterile water"},{"id":"B","text":"Keep the tube clamped with two padded clamps until the new unit arrives"},{"id":"C","text":"Cover the open end of the tube with a sterile gauze square"},{"id":"D","text":"Hold the open end of the tube well above the level of the client chest"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A temporary water seal lets trapped air escape while preventing atmospheric air from entering.","B":"Incorrect. Sustained clamping traps escaping air and risks a tension pneumothorax.","C":"Incorrect. Gauze is porous, so air still passes in both directions.","D":"Incorrect. Height does not stop air entering an open tube, and it does not restore a seal."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Restoring the water seal',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560022', 'MCQ',
 'A confused client pulls a chest tube completely out of the chest wall. Which action should the nurse take immediately?',
 'An open hole in the chest wall lets atmospheric air rush into the pleural space with every breath. A sterile occlusive dressing taped on three sides acts as a flutter valve: air trapped in the pleural space can escape under the loose edge, but air cannot be drawn back in. Sealing all four sides converts an open pneumothorax into a tension pneumothorax, which is far more dangerous.',
 '{"options":[{"id":"A","text":"Cover the site with a sterile occlusive dressing taped on three sides"},{"id":"B","text":"Cover the site with a sterile occlusive dressing sealed on all four sides"},{"id":"C","text":"Reinsert the tube through the same opening"},{"id":"D","text":"Lay the client flat and press over the opening with a gloved hand"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Taping three sides creates a one-way valve that lets air out but not in, and the nurse then stays with the client and summons help.","B":"Incorrect. A fully sealed dressing traps escaping air and can produce a tension pneumothorax.","C":"Incorrect. Reinserting a contaminated tube is outside the nursing role and introduces infection.","D":"Incorrect. A bare gloved hand is neither sterile nor an effective one-way seal."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Accidental tube removal',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560023', 'SATA',
 'A visitor knocks over the chest drainage unit of a client who is sitting in a chair. The unit is intact and the tubing is still connected. Which actions should the nurse take? Select all that apply.',
 'A knocked-over unit is a recoverable event, not an emergency, provided the system stays intact and connected. The correction is to stand it upright at once, confirm that the water-seal chamber still holds the prescribed volume of water, and then assess the client for any change in breathing. Clamping the tube adds risk without benefit, and replacing an intact system is unnecessary.',
 '{"options":[{"id":"A","text":"Return the unit to the upright position immediately"},{"id":"B","text":"Check that the water-seal chamber holds the prescribed volume of water and top it up if needed"},{"id":"C","text":"Assess respiratory rate, effort and oxygen saturation"},{"id":"D","text":"Clamp the tube for 30 minutes while the fluid settles"},{"id":"E","text":"Replace the whole drainage unit as a routine precaution"},{"id":"F","text":"Document the incident and continue to observe the client"}]}'::jsonb,
 '{"answers":["A","B","C","F"],"feedback":{"A":"Correct. Standing the unit upright restores the water seal and the correct suction level.","B":"Correct. Water may have spilled between chambers, so the seal volume is verified and corrected.","C":"Correct. The client is assessed for any respiratory change resulting from the interruption.","D":"Incorrect. Prolonged clamping traps air in the pleural space and risks a tension pneumothorax.","E":"Incorrect. An intact, connected system does not need replacing simply because it was tipped over.","F":"Correct. The event and the response are recorded and the client continues to be observed."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Unit knocked over',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_560024', 'SELECT_N',
 'A student nurse asks when a chest tube may be clamped. Which 3 situations should the nurse identify as acceptable reasons to clamp briefly, for no longer than about 15 seconds?',
 'Clamping is permitted only for short, purposeful moments in which leaving the tube open would be worse than closing it. Changing the drainage unit, tracing an air leak and a prescribed trial before tube removal all meet that test. Clamping for convenience during transfer, walking or pain is never acceptable, because trapped air can build pressure quickly and produce a tension pneumothorax.',
 '{"options":[{"id":"A","text":"While the drainage unit is being changed for a new one"},{"id":"B","text":"While the source of an air leak is being located"},{"id":"C","text":"While the client is assessed for tolerance before the tube is removed, on prescription"},{"id":"D","text":"While the client walks to the bathroom"},{"id":"E","text":"While the client is transferred to the radiology department"},{"id":"F","text":"Whenever the client reports pain at the insertion site"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. A momentary clamp prevents air entry during the seconds the system is open for a unit change.","B":"Correct. Brief sequential clamping identifies whether the leak is in the client or in the system.","C":"Correct. A prescribed clamping trial checks tolerance before removal.","D":"Incorrect. The unit travels with the client below chest level; clamping to walk is unnecessary and dangerous.","E":"Incorrect. The drainage system remains connected and upright during transfer; it is never clamped for the journey.","F":"Incorrect. Pain is treated with analgesia; clamping does nothing for it and adds serious risk."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Medical-Surgical', 'Respiratory',
 'Chest drainage', 'Clamping limits',
 'Hard', 'CURATOR_LABEL', 'Understand', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560025', 'SATA',
 'A client returns to the ward after a right pneumonectomy. Which statements about the care of this client are correct? Select all that apply.',
 'A pneumonectomy is different from every other chest surgery because there is no lung left on that side to re-expand. The empty space is meant to fill slowly with serous fluid and the mediastinum is meant to stay where it is, so any drain that is present is managed without suction and on the direct instruction of the surgeon. Positioning is on the back or the operative side so that the one remaining lung can expand fully, and a trachea that moves away from the operative side is a mediastinal shift needing urgent attention.',
 '{"options":[{"id":"A","text":"If a chest drain is present it is managed without suction and only as the surgeon directs"},{"id":"B","text":"The space left by the removed lung is expected to fill gradually with serous fluid"},{"id":"C","text":"The client is positioned on the back or on the operative side rather than on the unoperated side"},{"id":"D","text":"A trachea that has shifted away from the operative side must be reported at once"},{"id":"E","text":"Vigorous chest physiotherapy over the operative side should begin within the first hour"},{"id":"F","text":"The remaining lung is expected to expand and fill the empty space within 24 hours"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Suction would drag the mediastinum toward the empty space, so it is not applied after a pneumonectomy.","B":"Correct. Serous fluid gradually fills the space over weeks, which is the expected course.","C":"Correct. Lying on the operative side or the back leaves the remaining lung free to expand.","D":"Correct. Tracheal deviation signals a mediastinal shift and is an emergency.","E":"Incorrect. There is no lung on that side to clear, and vigorous physiotherapy over a fresh thoracotomy is inappropriate.","F":"Incorrect. The remaining lung does not cross the midline to fill the space; the space fills with fluid over time."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Pneumonectomy', 'Post-operative drainage differences',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560026', 'SATA',
 'The high-pressure alarm sounds on the ventilator of a client in the intensive care unit. Which causes should the nurse consider? Select all that apply.',
 'A high-pressure alarm means the ventilator is meeting more resistance than expected when it delivers the breath. Anything that narrows or blocks the path between the machine and the alveoli will do it: a kinked circuit, water pooled in a dependent loop, secretions in the airway, the client biting the tube, or reduced lung compliance from bronchospasm. A leak produces the opposite alarm because pressure never builds.',
 '{"options":[{"id":"A","text":"The ventilator tubing is kinked under the client arm"},{"id":"B","text":"Condensed water has collected in a dependent loop of the circuit"},{"id":"C","text":"Secretions are partly obstructing the airway"},{"id":"D","text":"The client is biting on the endotracheal tube"},{"id":"E","text":"The endotracheal tube cuff has deflated"},{"id":"F","text":"The circuit has come apart at the humidifier connection"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. A kinked circuit raises the resistance the ventilator must overcome.","B":"Correct. Pooled condensation obstructs gas flow and triggers the high-pressure alarm.","C":"Correct. Secretions narrow the airway and increase peak pressure.","D":"Correct. Biting occludes the tube and is a common cause in a waking client.","E":"Incorrect. A deflated cuff lets gas escape around the tube, which lowers pressure and triggers the low-pressure alarm.","F":"Incorrect. A disconnection is a leak and sets off the low-pressure alarm."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'High-pressure alarm causes',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_DO_560027', 'DRAG_ORDER',
 'The high-pressure alarm sounds on a ventilated client who is otherwise stable. Place the nurse actions in the order in which they should be carried out.',
 'High-pressure alarms are worked through from the least invasive cause outward. The circuit itself is checked first, because a kink or pooled water is corrected in seconds with no risk to the client. Only when the circuit is clear is the airway addressed, first by asking the client to cough and then by suctioning, which is invasive and briefly interrupts ventilation. The doctor is informed if the alarm still cannot be resolved.',
 '{"slots":[{"id":"s1","target_text":"1st"},{"id":"s2","target_text":"2nd"},{"id":"s3","target_text":"3rd"},{"id":"s4","target_text":"4th"}],"tokens":[{"id":"t1","text":"Straighten the ventilator tubing and free it from under the client"},{"id":"t2","text":"Empty the condensed water from the dependent loop of the circuit"},{"id":"t3","text":"Ask the client to cough and, if the airway is still noisy, suction the endotracheal tube"},{"id":"t4","text":"Inform the doctor that the alarm cannot be resolved"},{"id":"t5","text":"Silence the alarm permanently and continue with the medication round"}]}'::jsonb,
 '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'Working through a high-pressure alarm',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Place the options in the correct order.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560028', 'MCQ',
 'The low-pressure alarm sounds on the ventilator of a client in the intensive care unit. Which action should the nurse take FIRST?',
 'A low-pressure alarm means the ventilator cannot build the expected pressure, which happens when gas is escaping. The commonest reason is a disconnection or a loose connection somewhere in the circuit, so the first action is a systematic trace of the circuit from the client back to the machine. Suctioning and raising the tidal volume address problems the alarm is not reporting.',
 '{"options":[{"id":"A","text":"Trace the ventilator circuit from the client back to the machine, checking every connection"},{"id":"B","text":"Suction the endotracheal tube"},{"id":"C","text":"Increase the set tidal volume on the ventilator"},{"id":"D","text":"Ask the respiratory physiotherapist to review the client"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A low-pressure alarm signals a leak or disconnection, and tracing the circuit finds it fastest.","B":"Incorrect. Secretions raise pressure and trigger the high-pressure alarm, not the low-pressure one.","C":"Incorrect. Increasing the tidal volume masks the alarm without correcting the leak.","D":"Incorrect. Referral wastes time during an alarm the nurse can resolve directly."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'Low-pressure alarm',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560029', 'MCQ',
 'The low-pressure alarm continues to sound, the nurse can find no disconnection, and the oxygen saturation has fallen to 86% with visible respiratory distress. Which action is BEST?',
 'When the equipment cannot be made to deliver a reliable breath, the priority shifts from troubleshooting the machine to ventilating the client. Disconnecting the ventilator and using a bag-valve device with 100% oxygen guarantees oxygenation while help is summoned and the fault is investigated. Continuing to hunt for a leak, or adjusting settings on a machine that is not delivering, leaves the client hypoxic.',
 '{"options":[{"id":"A","text":"Disconnect the ventilator and manually ventilate with a bag-valve device and 100% oxygen while calling for help"},{"id":"B","text":"Silence the alarm and keep searching the circuit for the leak"},{"id":"C","text":"Add a further 10 mL of air to the endotracheal tube cuff"},{"id":"D","text":"Increase the fraction of inspired oxygen on the ventilator to 100%"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. When the ventilator cannot be trusted to deliver the breath, manual ventilation guarantees oxygenation.","B":"Incorrect. Silencing an alarm on a hypoxic client and continuing to search delays effective ventilation.","C":"Incorrect. Overinflating the cuff risks tracheal mucosal damage and may not be the fault at all.","D":"Incorrect. Raising the oxygen concentration on a machine that is not delivering the volume achieves nothing."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'Unresolved low-pressure alarm',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560030', 'MCQ',
 'A ventilated client is being considered for weaning. The arterial blood gas taken on 40% oxygen shows pH 7.36, PaCO2 42 mmHg, PaO2 88 mmHg and HCO3 24 mEq/L. How should the nurse interpret this result?',
 'All four values sit inside the normal ranges: pH 7.35 to 7.45, PaCO2 35 to 45 mmHg, PaO2 80 to 100 mmHg and bicarbonate 22 to 26 mEq/L. A client who maintains normal gas exchange on a modest oxygen concentration is demonstrating the respiratory reserve that weaning requires. Gases are only one of the criteria, but these ones raise no objection to a trial.',
 '{"options":[{"id":"A","text":"The values are within normal limits and support proceeding with a weaning trial"},{"id":"B","text":"The result shows respiratory acidosis and weaning should be postponed"},{"id":"C","text":"The result shows metabolic alkalosis and the potassium should be checked before weaning"},{"id":"D","text":"The PaO2 is too low for weaning and the oxygen concentration should be increased first"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Every value is normal on 40% oxygen, which is consistent with readiness for a weaning trial.","B":"Incorrect. Respiratory acidosis would show a pH below 7.35 with a PaCO2 above 45 mmHg; neither is present.","C":"Incorrect. Metabolic alkalosis would show a raised pH with a raised bicarbonate; both are normal here.","D":"Incorrect. A PaO2 of 88 mmHg is normal and needs no increase in oxygen."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'Arterial blood gases and weaning',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SELN_560031', 'SELECT_N',
 'The intensive care team is reviewing a ventilated client for a weaning trial. Which 3 findings indicate that the client is ready to begin?',
 'Weaning readiness is judged on the whole client, not on the ventilator settings alone. The client needs a stable cardiovascular state, adequate respiratory drive and effort, and enough alertness to cooperate with instructions and protect the airway. Active infection, fever and significant anaemia all increase the work of breathing or the oxygen demand and mean the trial should wait.',
 '{"options":[{"id":"A","text":"The client is alert and able to follow simple instructions"},{"id":"B","text":"Spontaneous respiratory effort is present with a stable rate and adequate tidal volume"},{"id":"C","text":"The client is haemodynamically stable and no longer needs vasopressor support"},{"id":"D","text":"The temperature is 38.9 °C with new purulent secretions"},{"id":"E","text":"The haemoglobin is 6.4 g/dL"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. The client must be alert enough to cooperate and to protect the airway once the tube is removed.","B":"Correct. Adequate spontaneous effort shows the respiratory drive needed to take over from the machine.","C":"Correct. Weaning increases the work of breathing, which an unstable circulation cannot support.","D":"Incorrect. Fever and purulent secretions signal an active chest infection, which increases oxygen demand and delays weaning.","E":"Incorrect. Significant anaemia reduces oxygen carriage and makes a successful trial less likely."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Medical-Surgical', 'Respiratory',
 'Mechanical ventilation', 'Readiness to wean',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560032', 'SATA',
 'A nurse is fitting axillary crutches for a client before discharge. Which observations show that the crutches are correctly fitted and being used correctly? Select all that apply.',
 'Axillary crutches are hand-weight-bearing devices, not underarm supports. A gap of two to three finger widths below the axilla, with the elbows flexed about 30 degrees at the hand grips, positions the client to take the whole body weight through the hands. Weight resting in the axillae compresses the brachial plexus and the vessels there, producing crutch palsy.',
 '{"options":[{"id":"A","text":"There is a gap of two to three finger widths between the axilla and the crutch pad"},{"id":"B","text":"The elbows are flexed about 30 degrees when the hands rest on the hand grips"},{"id":"C","text":"Body weight is taken through the hands rather than the underarms"},{"id":"D","text":"The crutch tips are placed about 15 to 20 centimetres in front of and to the side of the feet"},{"id":"E","text":"The crutch pads rest firmly in the armpits to give extra support"},{"id":"F","text":"The client leans onto the crutch pads while resting between steps"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. That gap keeps the pad clear of the axilla when the client stands upright.","B":"Correct. About 30 degrees of elbow flexion allows the arms to extend and lift the body weight.","C":"Correct. Hand weight-bearing is the defining principle of safe axillary crutch use.","D":"Correct. This tripod position gives a stable base before each step.","E":"Incorrect. Pressure in the axilla compresses nerves and vessels and causes crutch palsy.","F":"Incorrect. Resting on the pads is the same harmful pressure, simply held for longer."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal',
 'Crutch walking', 'Measuring and fitting',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560033', 'MCQ',
 'A client who has been using axillary crutches for two weeks reports numbness and tingling in both hands and a grip that has become weak. How should the nurse interpret this finding?',
 'The brachial plexus runs through the axilla and is easily compressed between the crutch pad and the chest wall. Sustained pressure there produces crutch palsy, which appears as numbness, tingling and weakness in the hand and forearm. It is preventable and reversible: the crutches are re-measured and the client is retaught to carry the weight on the hands.',
 '{"options":[{"id":"A","text":"The client is resting body weight in the axillae and compressing the nerves there"},{"id":"B","text":"The crutches are too short, so the elbows are being over-extended"},{"id":"C","text":"This is an expected effect of unaccustomed exercise and will settle without action"},{"id":"D","text":"The client is developing a deep vein thrombosis in the arm"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Pressure on the brachial plexus in the axilla causes crutch palsy, with numbness, tingling and weak grip.","B":"Incorrect. Crutches that are too short cause stooping and back strain rather than nerve symptoms in the hands.","C":"Incorrect. Nerve compression symptoms are never dismissed as normal; unaddressed, the damage can become lasting.","D":"Incorrect. A venous thrombosis causes unilateral swelling, warmth and pain, not bilateral numbness and weakness."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Neurological',
 'Crutch walking', 'Crutch palsy',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560034', 'MCQ',
 'A 22-year-old client has a fractured right ankle in a cast and is not permitted to place any weight on the right leg. The left leg is strong and unaffected. Which crutch gait should the nurse teach?',
 'The gait is chosen from the pattern of weakness. When one leg is affected and the other is sound, an odd-numbered gait is used: in the three-point gait both crutches and the affected leg advance together as one point of support, then the strong leg swings through. Even-numbered gaits require both legs to bear weight, and swing-through gaits are for clients whose legs bear no weight at all.',
 '{"options":[{"id":"A","text":"Three-point gait"},{"id":"B","text":"Four-point gait"},{"id":"C","text":"Two-point gait"},{"id":"D","text":"Swing-through gait"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. One affected leg and one strong leg calls for an odd-numbered gait, and the three-point gait keeps all weight off the right ankle.","B":"Incorrect. The four-point gait requires weight-bearing on both legs, which is not permitted here.","C":"Incorrect. The two-point gait also requires partial weight-bearing on both legs.","D":"Incorrect. The swing-through gait is for a client who cannot bear weight on either leg."}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal',
 'Crutch walking', 'Matching gait to weakness',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_CLZ_560035', 'CLOZE',
 'A physiotherapist and nurse plan crutch teaching for two clients. A client with weakness in both legs from a neurological condition, who can still bear some weight on each leg, is taught a {1}. A client with paraplegia who can bear no weight on either leg is taught a {2}.',
 'The rule is simple once the pattern of weakness is named. When both legs are affected but both can bear some weight, an even-numbered gait is used, moving one crutch and the opposite leg at a time so that several points of contact stay on the floor. When neither leg can bear weight, the legs are lifted clear of the floor entirely and swung past the crutches.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"four-point gait"},{"id":"c2","text":"three-point gait"},{"id":"c3","text":"swing-through gait"}]},{"id":"b2","choices":[{"id":"c1","text":"two-point gait"},{"id":"c2","text":"swing-through gait"},{"id":"c3","text":"three-point gait"}]}]}'::jsonb,
 '{"answers":{"b1":"c1","b2":"c2"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal',
 'Crutch walking', 'Even-numbered and swing gaits',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 'Complete the sentence by choosing from each drop-down.', 2, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MMR_560036', 'MATRIX_MR',
 'A nurse revises mobility aids with a group of students. For each teaching point, indicate which device or devices it applies to. A teaching point may apply to more than one device.',
 'Each device has one rule that belongs to it alone and some that are shared. A cane is held on the side of the stronger leg so that the load is shifted away from the weak side, crutches are the device on which weight must never rest in the axillae, and a walking frame must never be used on stairs. Advancing the device first and then the weaker leg, and checking the rubber tips for wear, apply more widely.',
 '{"rows":[{"id":"r1","text":"Hold or position the device on the side of the stronger leg"},{"id":"r2","text":"Bear weight through the hands, never through the underarms"},{"id":"r3","text":"Advance the device first, then the weaker leg, then the stronger leg"},{"id":"r4","text":"Never use the device to climb a flight of stairs"},{"id":"r5","text":"Check the rubber tips for wear before each use"}],"columns":[{"id":"c1","text":"Cane"},{"id":"c2","text":"Axillary crutches"},{"id":"c3","text":"Walking frame"}],"row_label":"Teaching point"}'::jsonb,
 '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c1","c3"],"r4":["c3"],"r5":["c1","c2","c3"]},"feedback":{}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Musculoskeletal',
 'Assistive devices', 'Canes, crutches and walking frames',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply for each row.', 8, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560037', 'MCQ',
 'A client with a healing left leg fracture is practising stairs with crutches. Which statement shows that the teaching has been understood?',
 'The stronger leg always travels toward the step it must lift the body onto, and the weaker leg always travels with the crutches. Going up, the strong leg steps first and pulls the body up; coming down, the crutches and the weak leg go down first so that the strong leg controls the descent. The memory hook is up with the good and down with the bad.',
 '{"options":[{"id":"A","text":"Going up, my strong right leg goes first; coming down, the crutches and my weak left leg go first."},{"id":"B","text":"Going up, my weak left leg goes first; coming down, my strong right leg goes first."},{"id":"C","text":"The crutches go first whether I am going up or coming down."},{"id":"D","text":"I take both steps with the same foot before I move the crutches at all."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Up with the stronger leg and down with the weaker leg and the crutches is the safe sequence.","B":"Incorrect. This reverses the rule and puts the weak leg in the position that must lift the whole body weight.","C":"Incorrect. Leading with the crutches going up leaves the client unsupported on the higher step.","D":"Incorrect. Taking two steps with one foot before moving the crutches leaves the client without a stable base."}}'::jsonb,
 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Medical-Surgical', 'Musculoskeletal',
 'Crutch walking', 'Stairs',
 'Very easy', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560038', 'SATA',
 'A nurse visits an older client at home to teach the use of a standard walking frame. Which instructions should be given? Select all that apply.',
 'A walking frame is only as stable as the surface it stands on and the way the client positions the body within it. All four legs must be flat on the floor before any step is taken, and the client steps into the frame rather than past it, which keeps the centre of gravity inside the base of support. Hanging bags on the frame shifts that base and makes it tip, and a frame must never be taken onto stairs.',
 '{"options":[{"id":"A","text":"Place all four legs of the frame flat on the floor before stepping"},{"id":"B","text":"Move the frame a short step ahead and step into it, not past it"},{"id":"C","text":"Remove loose rugs and trailing flexes from the walking route"},{"id":"D","text":"Wear well-fitting shoes with non-slip soles rather than backless slippers"},{"id":"E","text":"Hang a shopping bag from the front of the frame to keep the hands free"},{"id":"F","text":"Use the frame to climb the stairs at home"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. A frame tilted on two legs offers no support and is a common cause of falls.","B":"Correct. Stepping into the frame keeps the client inside the base of support.","C":"Correct. Rugs and flexes catch the frame legs and are removed before the client mobilises.","D":"Correct. Secure footwear is part of safe mobilising with any aid.","E":"Incorrect. A bag hung on the frame shifts the centre of gravity and makes it tip forward.","F":"Incorrect. Walking frames are never used on stairs; a different plan is needed for a client with stairs at home."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Musculoskeletal',
 'Walking frame', 'Safe use at home',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560039', 'SATA',
 'A client has had continuous nasogastric suction for three days after abdominal surgery. Which findings would the nurse expect? Select all that apply.',
 'Gastric aspirate is rich in hydrochloric acid, so removing it continuously strips hydrogen ions from the body and produces a metabolic alkalosis. Bicarbonate rises with the pH. Potassium falls for two reasons: it is lost in the aspirate, and it moves into the cells as hydrogen moves out of them to buffer the alkalosis. Compensation is respiratory, so breathing slows and shallows to retain carbon dioxide.',
 '{"options":[{"id":"A","text":"Arterial pH 7.50"},{"id":"B","text":"Serum bicarbonate 32 mEq/L"},{"id":"C","text":"Serum potassium 3.0 mEq/L"},{"id":"D","text":"Slow, shallow breathing"},{"id":"E","text":"Deep, rapid Kussmaul respirations"},{"id":"F","text":"Serum bicarbonate 16 mEq/L"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Loss of gastric acid raises the pH into alkalosis.","B":"Correct. Bicarbonate rises relative to the remaining hydrogen ions.","C":"Correct. Potassium is lost in the aspirate and also shifts into the cells during alkalosis.","D":"Correct. Slow shallow breathing retains carbon dioxide as respiratory compensation for the alkalosis.","E":"Incorrect. Kussmaul respirations blow off carbon dioxide to compensate for metabolic acidosis, which is the opposite disturbance.","F":"Incorrect. A low bicarbonate belongs to metabolic acidosis, not to acid loss from suction."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Gastrointestinal',
 'Acid-base balance', 'Metabolic alkalosis from acid loss',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560040', 'MCQ',
 'A woman in the first stage of labour is breathing rapidly and deeply between contractions and now reports tingling around the mouth and in the fingers with light-headedness. Which action should the nurse take?',
 'Rapid deep breathing blows off carbon dioxide faster than the body produces it, so the pH rises and a respiratory alkalosis develops. The tingling and light-headedness come from the fall in ionised calcium that alkalosis produces. Slowing the breathing, and rebreathing exhaled air from cupped hands, restores the carbon dioxide level and the symptoms settle within minutes.',
 '{"options":[{"id":"A","text":"Coach the woman to slow her breathing and to breathe into her cupped hands between contractions"},{"id":"B","text":"Apply oxygen at 10 litres per minute through a face mask"},{"id":"C","text":"Ask the woman to take several fast deep breaths to clear the tingling"},{"id":"D","text":"Lay the woman flat on her back and raise her legs"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Slowing the rate and rebreathing exhaled carbon dioxide corrects the respiratory alkalosis directly.","B":"Incorrect. The problem is too little carbon dioxide, not too little oxygen, so extra oxygen does not help.","C":"Incorrect. More rapid breathing removes still more carbon dioxide and worsens the alkalosis.","D":"Incorrect. Lying flat on the back in labour compresses the vena cava and does not address the breathing pattern."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Respiratory',
 'Acid-base balance', 'Respiratory alkalosis from hyperventilation',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_560041', 'MCQ',
 'A client using morphine by patient-controlled analgesia has a respiratory rate of 8 breaths per minute and is difficult to rouse. The arterial blood gas shows pH 7.26, PaCO2 62 mmHg and HCO3 25 mEq/L. Which interpretation and action are correct?',
 'Opioids depress the respiratory centre, so carbon dioxide is retained and the pH falls. A low pH with a high PaCO2 and a normal bicarbonate is an uncompensated respiratory acidosis, and the normal bicarbonate confirms it developed too quickly for the kidneys to compensate. The treatment is to stop the cause and restore ventilation: stop the opioid, stimulate and support breathing, and give naloxone if the client cannot be roused.',
 '{"options":[{"id":"A","text":"Uncompensated respiratory acidosis; stop the patient-controlled analgesia, stimulate the client to breathe deeply and prepare to give naloxone"},{"id":"B","text":"Metabolic acidosis; prepare to give intravenous sodium bicarbonate"},{"id":"C","text":"Respiratory alkalosis; encourage the client to rebreathe from cupped hands"},{"id":"D","text":"Compensated metabolic alkalosis; continue to observe and repeat the gas in four hours"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. A low pH with a raised PaCO2 and normal bicarbonate is uncompensated respiratory acidosis from opioid-induced hypoventilation.","B":"Incorrect. Metabolic acidosis would show a low bicarbonate; the bicarbonate here is normal.","C":"Incorrect. Alkalosis would raise the pH above 7.45; this pH is low.","D":"Incorrect. Waiting four hours with a respiratory rate of 8 breaths per minute leaves a deteriorating client untreated."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Medical-Surgical', 'Respiratory',
 'Acid-base balance', 'Respiratory acidosis from hypoventilation',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_560042', 'MATRIX',
 'A nurse is teaching acid-base balance to a group of students using clients on the ward. For each client, indicate the acid-base disturbance that would be expected.',
 'The cause names the disturbance before any number is read. A respiratory disturbance follows a change in ventilation: too little breathing retains carbon dioxide and produces acidosis, too much blows it off and produces alkalosis. A metabolic disturbance follows a change in acid or bicarbonate load: ketones add acid, while losing gastric acid leaves bicarbonate in relative excess.',
 '{"rows":[{"id":"r1","text":"A client in diabetic ketoacidosis with a blood glucose of 28 mmol/L"},{"id":"r2","text":"A client vomiting repeatedly for three days with a gastric outlet obstruction"},{"id":"r3","text":"A client rescued from a swimming pool who has aspirated water and is barely breathing"},{"id":"r4","text":"A client having a panic attack who is breathing 40 breaths per minute"},{"id":"r5","text":"A client with advanced chronic obstructive pulmonary disease who retains carbon dioxide"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Respiratory alkalosis"},{"id":"c3","text":"Metabolic acidosis"},{"id":"c4","text":"Metabolic alkalosis"}],"row_label":"Client"}'::jsonb,
 '{"cells":{"r1":"c3","r2":"c4","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem',
 'Acid-base balance', 'Matching cause to disturbance',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select one column for each row.', 5, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560043', 'MCQ',
 'A client is admitted with severe metabolic acidosis. Which serum potassium result should the nurse expect, and for what reason?',
 'Hydrogen and potassium trade places across the cell membrane to defend the pH. In acidosis the excess hydrogen ions move into the cells and potassium moves out into the blood, so the serum potassium rises even when total body potassium is normal or low. The reverse happens in alkalosis. This matters clinically because correcting the acidosis drives potassium back into the cells, and the serum level can fall sharply during treatment.',
 '{"options":[{"id":"A","text":"Raised, because hydrogen ions move into the cells and potassium moves out into the blood"},{"id":"B","text":"Lowered, because hydrogen ions move out of the cells and potassium moves in"},{"id":"C","text":"Unchanged, because serum potassium is not affected by pH"},{"id":"D","text":"Lowered, because the kidneys excrete potassium in order to retain hydrogen"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. The hydrogen and potassium exchange across the cell membrane raises the serum potassium in acidosis.","B":"Incorrect. That shift describes alkalosis, in which the serum potassium falls.","C":"Incorrect. Serum potassium moves predictably with pH, which is why it is checked in every acid-base disturbance.","D":"Incorrect. The kidneys retain hydrogen and excrete potassium in alkalosis, not in acidosis."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem',
 'Acid-base balance', 'Potassium and pH',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560044', 'MCQ',
 'A client returns to the ward two hours after a thyroidectomy. Which assessment is the PRIORITY at this stage?',
 'The complication that dominates after thyroid surgery changes with time. In the first hours the danger is airway obstruction from swelling or from a haematoma pressing on the trachea, so listening for stridor and checking for blood is the priority. Blood tracks backward under gravity, so the dressing at the front of the neck can look dry while a haematoma collects behind. Hypocalcaemia and thyroid storm come later; infection later still.',
 '{"options":[{"id":"A","text":"Listen for stridor and slide a gloved hand behind the neck to feel for pooled blood"},{"id":"B","text":"Tap over the facial nerve to check for the Chvostek sign"},{"id":"C","text":"Measure the temperature for early signs of wound infection"},{"id":"D","text":"Check the serum thyroid-stimulating hormone result"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Airway obstruction from oedema or a haematoma is the immediate threat in the first hours after surgery.","B":"Incorrect. Hypocalcaemia from parathyroid injury usually appears 24 to 72 hours after surgery, not at two hours.","C":"Incorrect. Wound infection is a later complication and is not the priority now.","D":"Incorrect. Thyroid function results guide replacement therapy over weeks and have no bearing on the immediate airway risk."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine',
 'Thyroidectomy', 'Early post-operative priority',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_560045', 'MATRIX',
 'A nurse is caring for several clients on the second day after thyroid surgery. For each finding, indicate whether it is expected at this stage or must be reported immediately.',
 'Some post-thyroidectomy findings are the ordinary consequences of handling tissue around the larynx: a hoarse weak voice, mild pain on swallowing and a little serous ooze. What must not be accepted are the three complications that kill: airway obstruction, signalled by a crowing inspiratory noise and restlessness; hypocalcaemic tetany, signalled by tingling of the fingers and around the mouth; and thyroid storm, signalled by high fever, extreme tachycardia and agitation.',
 '{"rows":[{"id":"r1","text":"A hoarse, weak voice"},{"id":"r2","text":"A crowing sound on inspiration with restlessness"},{"id":"r3","text":"Mild discomfort on swallowing that is relieved by the prescribed analgesia"},{"id":"r4","text":"Tingling of the fingertips and around the mouth"},{"id":"r5","text":"Temperature 39.4 °C with a pulse of 148 beats per minute and agitation"},{"id":"r6","text":"A small amount of serous ooze on the neck dressing"}],"columns":[{"id":"c1","text":"Expected at this stage"},{"id":"c2","text":"Report immediately"}],"row_label":"Finding"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c2","r6":"c1"},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Medical-Surgical', 'Endocrine',
 'Thyroidectomy', 'Expected findings and red flags',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select one column for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_560046', 'SATA',
 'Thirty-six hours after a total thyroidectomy the nurse suspects hypocalcaemia. Which findings would support this? Select all that apply.',
 'The parathyroid glands sit on the back of the thyroid and can be bruised or removed during a total thyroidectomy. Without parathyroid hormone the serum calcium falls, and nerves and muscles become hyperexcitable. This shows first as tingling of the lips, nose and fingertips, then as twitching and cramping, and can progress to laryngeal spasm. The Chvostek and Trousseau signs are the bedside tests, and calcium gluconate is kept available.',
 '{"options":[{"id":"A","text":"Tingling of the lips, nose and fingertips"},{"id":"B","text":"Twitching of the facial muscles when the nerve is tapped in front of the ear"},{"id":"C","text":"Carpal spasm after a blood pressure cuff is inflated on the upper arm for a few minutes"},{"id":"D","text":"Cramping of the muscles of the hands and feet"},{"id":"E","text":"A blood pressure of 168/96 mmHg with a flushed face"},{"id":"F","text":"Deep tendon reflexes that cannot be elicited"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Perioral and fingertip tingling is the earliest sign of falling calcium.","B":"Correct. That is the Chvostek sign, a bedside indicator of neuromuscular irritability.","C":"Correct. That is the Trousseau sign, carpal spasm provoked by the inflated cuff.","D":"Correct. Muscle cramping reflects the same hyperexcitability and can progress to tetany.","E":"Incorrect. Hypertension with flushing is not a feature of hypocalcaemia.","F":"Incorrect. Reflexes become brisk in hypocalcaemia; absent reflexes suggest a high calcium or magnesium level instead."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine',
 'Thyroidectomy', 'Hypocalcaemic tetany',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_560047', 'SELECT_N',
 'A client who had a subtotal thyroidectomy eight hours ago becomes acutely unwell. Which 3 findings would indicate thyroid storm?',
 'Thyroid storm is an uncontrolled release of thyroid hormone that turns every metabolic process up at once, and it is a risk after a subtotal thyroidectomy in a client who was not fully euthyroid before surgery. The picture is a high fever, extreme tachycardia that may become an arrhythmia, and central nervous system excitement with agitation, tremor and confusion. Bradycardia with cold skin, and a positive Trousseau sign, belong to different complications entirely.',
 '{"options":[{"id":"A","text":"Temperature 40.1 °C"},{"id":"B","text":"Heart rate 156 beats per minute with atrial fibrillation"},{"id":"C","text":"Agitation, tremor and confusion"},{"id":"D","text":"Cold dry skin with a pulse of 52 beats per minute"},{"id":"E","text":"A positive Trousseau sign"},{"id":"F","text":"A hoarse voice with mild discomfort on swallowing"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Hyperpyrexia is a defining feature of thyroid storm.","B":"Correct. Extreme tachycardia, often with atrial fibrillation, reflects the cardiac effect of the hormone surge.","C":"Correct. Agitation, tremor and confusion reflect central nervous system overstimulation.","D":"Incorrect. Bradycardia and cold skin suggest the opposite state, hypothyroidism or myxoedema.","E":"Incorrect. A positive Trousseau sign indicates hypocalcaemia from parathyroid injury, a different complication.","F":"Incorrect. A hoarse voice and mild pain on swallowing are expected after thyroid surgery and say nothing about a hormone surge."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine',
 'Thyroid storm', 'Recognition after surgery',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560048', 'MCQ',
 'A client with hyperthyroidism asks why the antithyroid medicine and the iodine preparation must be continued right up to the day of the thyroidectomy when other medicines are being stopped. Which response by the nurse is correct?',
 'Thyroid medicines are not simply withheld before surgery because the whole purpose of the preoperative period is to make the client euthyroid. Antithyroid drugs bring the circulating hormone level down so that the surgical stress cannot provoke a thyroid storm, and iodine reduces the size and vascularity of the gland so that the operation bleeds less. After a total thyroidectomy the client then begins lifelong thyroid hormone replacement.',
 '{"options":[{"id":"A","text":"They bring the thyroid hormone level down to normal and reduce the blood supply to the gland, which lowers the risk of thyroid storm and of bleeding during surgery."},{"id":"B","text":"They protect the parathyroid glands from injury while the thyroid is being removed."},{"id":"C","text":"They prevent the vocal cords from swelling after the breathing tube is removed."},{"id":"D","text":"They keep the blood glucose stable during the period when you are unable to eat."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Achieving a euthyroid state and shrinking the vascular gland are the two reasons these medicines continue up to surgery.","B":"Incorrect. The parathyroid glands are protected by surgical technique, not by antithyroid medicines.","C":"Incorrect. Laryngeal oedema is managed post-operatively; these medicines have no such effect.","D":"Incorrect. Thyroid medicines do not control blood glucose."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Medical-Surgical', 'Endocrine',
 'Thyroidectomy', 'Preoperative euthyroid state',
 'Very hard', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560049', 'MCQ',
 'A client with Addison disease is admitted after two days of vomiting and diarrhoea. The blood pressure is 78/48 mmHg, the pulse is 122 beats per minute and the client is drowsy. Which action is the PRIORITY?',
 'A client with adrenal insufficiency cannot raise cortisol in response to stress, so an ordinary illness that another person would shrug off strips the circulation of its support and produces an addisonian crisis. The presentation is profound hypotension, tachycardia and altered consciousness with hyponatraemia and hyperkalaemia. Treatment is immediate volume replacement with intravenous saline together with intravenous hydrocortisone; nothing given by mouth will work fast enough or be absorbed reliably.',
 '{"options":[{"id":"A","text":"Establish intravenous access and start the prescribed intravenous normal saline with intravenous hydrocortisone"},{"id":"B","text":"Offer oral rehydration solution and encourage frequent small sips"},{"id":"C","text":"Weigh the client and begin a strict fluid balance chart"},{"id":"D","text":"Move the client to a quiet side room and restrict visitors"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Circulatory collapse in an addisonian crisis is reversed only by intravenous fluid and intravenous steroid replacement.","B":"Incorrect. A vomiting, drowsy client cannot absorb oral fluid, and the volume deficit is far beyond what sips could correct.","C":"Incorrect. Monitoring is important but does nothing for a client who is shocked now.","D":"Incorrect. Reducing stimulation is supportive care and does not treat the crisis."}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine',
 'Adrenal insufficiency', 'Addisonian crisis',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_560050', 'SELECT_N',
 'A client is going home on lifelong hydrocortisone replacement for adrenal insufficiency. Which 3 instructions are essential?',
 'Replacement steroid is doing the job the adrenal glands can no longer do, so the dose can never simply stop and it must be able to rise when the body is stressed. Fever, infection, injury, vomiting and surgery all increase the requirement, and the prescriber sets out in advance how much to take on those days. Identification that tells a stranger about the condition is essential, because a client found collapsed needs hydrocortisone before any history can be taken.',
 '{"options":[{"id":"A","text":"Never stop the medicine suddenly, even on days when you feel completely well"},{"id":"B","text":"Follow the agreed plan to increase the dose during fever, infection, injury or surgery"},{"id":"C","text":"Wear a medical alert bracelet and carry a steroid card at all times"},{"id":"D","text":"Halve the dose on days spent resting at home"},{"id":"E","text":"Take the whole daily dose at bedtime"},{"id":"F","text":"Stop the medicine for a week if you gain weight"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Abrupt withdrawal leaves the client with no circulating cortisol and precipitates a crisis.","B":"Correct. The body cannot mount its own stress response, so the dose must be raised for the client.","C":"Correct. Identification allows emergency hydrocortisone to be given when the client cannot explain the condition.","D":"Incorrect. The dose is not reduced for rest days; the requirement is constant and rises with stress.","E":"Incorrect. Replacement mimics the natural rhythm, with the larger part taken in the morning.","F":"Incorrect. Stopping the medicine for any reason without advice risks an addisonian crisis."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Medical-Surgical', 'Endocrine',
 'Corticosteroid replacement', 'Sick-day rules',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MMR_560051', 'MATRIX_MR',
 'A nurse teaches students about the two ends of the adrenal spectrum. For each feature, indicate whether it belongs to adrenal insufficiency, to cortisol excess, or to both.',
 'Too little cortisol and too much cortisol produce opposite pictures in almost every respect. Insufficiency brings weight loss, low blood pressure, salt craving and, when the pituitary drives the adrenal glands hard, bronze pigmentation of the skin and gums. Excess brings central weight gain with a rounded face, a fatty pad between the shoulders, thin bruisable skin and wasted limb muscles. Blood glucose must be watched in both, because insufficiency tends to hypoglycaemia and excess to hyperglycaemia.',
 '{"rows":[{"id":"r1","text":"Bronze pigmentation of the skin and the gums"},{"id":"r2","text":"A rounded face, a fatty pad between the shoulders and thin, easily bruised skin"},{"id":"r3","text":"Blood glucose must be monitored regularly"},{"id":"r4","text":"Blood pressure tends to fall and salt craving is common"},{"id":"r5","text":"Weight loss with nausea, vomiting and fatigue"},{"id":"r6","text":"Wasting of the limb muscles alongside central weight gain"}],"columns":[{"id":"c1","text":"Adrenal insufficiency"},{"id":"c2","text":"Cortisol excess"}],"row_label":"Feature"}'::jsonb,
 '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c1","c2"],"r4":["c1"],"r5":["c1"],"r6":["c2"]},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine',
 'Adrenal disorders', 'Insufficiency and cortisol excess',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 7, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_560052', 'MCQ',
 'A client who has taken long-term corticosteroids for an autoimmune condition has developed a rounded face, central weight gain and increased facial hair, and tells the nurse: I cannot bear to look in the mirror or to see my friends any more. Which response by the nurse is most appropriate?',
 'The physical changes of cortisol excess are visible, unwanted and often the hardest part of treatment for the client to bear. An open invitation to describe the distress acknowledges it and gives the nurse the information needed to help, whereas reassurance, correction or a call to be grateful all close the conversation down. Once the client has been heard, the nurse can explain that many of these changes ease if the dose can be reduced, while stressing that the medicine is never stopped abruptly.',
 '{"options":[{"id":"A","text":"Tell me what worries you most about the changes you have noticed."},{"id":"B","text":"You should be grateful that the medicine is keeping your disease under control."},{"id":"C","text":"These changes are permanent, so it is better to accept them now."},{"id":"D","text":"Do not worry about it, nobody else will even notice."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. An open invitation to talk acknowledges the distress and allows the nurse to understand what matters most to this client.","B":"Incorrect. Telling the client to be grateful dismisses a genuine loss and shuts the conversation down.","C":"Incorrect. This is both discouraging and inaccurate, as many changes ease when the dose can be reduced.","D":"Incorrect. False reassurance denies the reality of visible changes and blocks further discussion."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Endocrine',
 'Corticosteroid therapy', 'Body image and altered appearance',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');
